func fakePNG(w, h int) []byte {
	b := []byte("\x89PNG\r\n\x1a\n")
	b = append(b, 0, 0, 0, 13)
	b = append(b, []byte("IHDR")...)
	var len4 [4]byte
	binary.BigEndian.PutUint32(len4[:], uint32(w))
	b = append(b, len4[:]...)
	var len4h [4]byte
	binary.BigEndian.PutUint32(len4h[:], uint32(h))
	b = append(b, len4h[:]...)
	return append(b, bytes.Repeat([]byte{0}, 8)...)
}

