			}
			nb := cb
			nb.converted = true
			if r.ok && strings.TrimSpace(r.ascii) != "" {
				nb.code = strings.TrimSuffix(r.ascii, "\n")
			}
			l.items[i] = nb
			applied++
			break
		}
	}
	return l, applied
}

