	t.Setenv("PATH", t.TempDir())
	r := newRig(t).seed("```plantuml\nAlice -> Bob: hi\n```")
	id := r.m.diagramJobs()[0].id
	before := findCode(t, r.m.chat, id).code

	cmd := r.m.pendingDiagrams()
	if cmd == nil {
		t.Fatal("expected a conversion cmd")
