// PNGDims liefert die Pixelmasse eines PNG (fuer das Fit-auf-Hoehe).
func PNGDims(pngBytes []byte) (w, h int, ok bool) {
	img, err := png.Decode(bytes.NewReader(pngBytes))
	if err != nil {
		return 0, 0, false
	}
	b := img.Bounds()
	return b.Dx(), b.Dy(), true
}

func PNGToANSI(pngBytes []byte, maxCols int) []string {
	img, err := png.Decode(bytes.NewReader(pngBytes))
	if err != nil {
		return nil
	}
	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	if w <= 0 || h <= 0 {
		return nil
	}
	cols := maxCols
	if cols > w {
		cols = w // kleine Bilder nicht unscharf hochskalieren
	}
	if cols < 1 {
		cols = 1
	}
	rows := (h*cols + w/2) / w / 2
	if rows < 1 {
		rows = 1
	}
	px := func(x, y int) (uint8, uint8, uint8) {
		if x >= w {
			x = w - 1
		}
		if y >= h {
			y = h - 1
		}
		r, g, bl, a := img.At(b.Min.X+x, b.Min.Y+y).RGBA()
		af := float64(a) / 65535.0
		mix := func(v uint32) uint8 {
			return uint8(float64(v>>8)*af + 255*(1-af))
		}
		return mix(r), mix(g), mix(bl)
	}
	out := make([]string, 0, rows)
	for r := 0; r < rows; r++ {
		var sb strings.Builder
		for c := 0; c < cols; c++ {
			x := c
			y1 := (2 * r * h) / (rows * 2)
			y2 := ((2*r + 1) * h) / (rows * 2)
			if y1 >= h {
				y1 = h - 1
			}
			if y2 >= h {
				y2 = h - 1
			}
			tr, tg, tb := px(x, y1)
			br, bg, bb := px(x, y2)
			fmt.Fprintf(&sb, "\x1b[38;2;%d;%d;%d;48;2;%d;%d;%dm▀", tr, tg, tb, br, bg, bb)
		}
		out = append(out, sb.String())
	}
	return out
}

