// NewImageBlock baut den Bildblock: PNG-Dimensionen aus dem IHDR-Chunk.
func NewImageBlock(png []byte, ascii string, useImages bool, caps TermCaps, copyFn CopyFunc, th *render.Theme) ImageBlock {
	w, h, ok := pngDims(png)
