package tui

import (
	"encoding/binary"
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"heron/internal/render"
)

// ImageBlock zeigt ein Diagramm als PNG ueber das Kitty-Graphics-Protokoll
// mit Unicode-Platzhaltern (FR-27): Das Bild ist echte Zellen im Textfluss —
// es steht am Ort des Codeblocks und scrollt mit dem Inhalt. Aspekt ueber
// echte Zellpixel (CSI 16 t). Terminals ohne Platzhalter-Unterstuetzung
// rendern den ASCII-/Roh-Text als CodeBlock-Fallback (FR-6).
//
// Metriken:
//  1. schnell  — PNG einmalig per kittyTransmit (a=t,i=<id>) uebertragen,
//     danach referenzieren nur Platzhalter (a=p,i=<id>) die stabile Bild-ID.
//     Kein Re-Decode, kein Re-Transmit pro Frame.
//  2. richtige Groesse — rowsFor() rechnet aus Blockbreite, Bildpixeln und
//     echter Zellgroesse (CellW/CellH) die Terminal-Zeilen; das Terminal
//     skaliert das Truecolor-PNG selbst (s=/v=).
//  3. scrollt mit — Platzhalter sind Zellen; der Block hat Height()==rows und
//     folgt der Blockliste.
type ImageBlock struct {
	id       int
	png      []byte
	pngW     int
	pngH     int
	useImg   bool
	caps     TermCaps
	ascii    string
	fallback CodeBlock
	copyFn   CopyFunc
	focused  bool
	hover    bool
	marked   bool
	th       *render.Theme
}

// NewImageBlock baut den Bildblock; Dimensionen aus dem IHDR-Chunk.
func NewImageBlock(png []byte, ascii string, useImg bool, caps TermCaps, copyFn CopyFunc, th *render.Theme) ImageBlock {
	w, h, ok := pngDimsFromBytes(png)
	if !ok {
		w, h = 400, 300
	}
	b := ImageBlock{
		png:      png,
		pngW:     w,
		pngH:     h,
		useImg:   useImg,
		caps:     caps,
		ascii:    strings.TrimSuffix(ascii, "\n"),
		fallback: NewCodeBlock("text", ascii, nil),
		copyFn:   copyFn,
		th:       th,
	}
	b.fallback.th = th
	return b
}

// pngDimsFromBytes liest Breite/Hoehe aus dem IHDR-Chunk (Header only).
func pngDimsFromBytes(b []byte) (int, int, bool) {
	if len(b) < 24 || string(b[:8]) != "\x89PNG\r\n\x1a\n" {
		return 0, 0, false
	}
	w := int(binary.BigEndian.Uint32(b[16:20]))
	h := int(binary.BigEndian.Uint32(b[20:24]))
	return w, h, w > 0 && h > 0
}

// colsFor begrenzt die Darstellung auf die Blockbreite.
func (b ImageBlock) colsFor(width int) int {
	c := width - 2
	if c < 10 {
		c = 10
	}
	return c
