func (l BlockList) reveal(idx int) BlockList {
	w := l.Width()
	y := 0
	for i := 0; i < idx; i++ {
		y += l.items[i].Height(w)
	}
	h := l.items[idx].Height(w)
	if y < l.offset {
		l.offset = y
		l.follow = false
	}
	if l.height > 0 && y+h > l.offset+l.height {
		l.offset = y + h - l.height
		l.follow = l.offset >= l.totalLines()-l.height
	}
	return l.clamp()
}

