// all stacks every widget into a full-height line list (with blank padding).
func (l BlockList) all() (lines []string, total int) {
	w := l.Width()
	for _, it := range l.items {
		h := it.Height(w)
		view := strings.Split(it.View(w), "\n")
		for len(view) < h {
			view = append(view, "")
		}
		lines = append(lines, view...)
		total += h
	}
	return lines, total
}

func (l BlockList) View() string {
	lines, total := l.all()
	if total == 0 {
		return ""
	}
	if l.height <= 0 {
		return strings.Join(lines, "\n")
	}
	left := l.offset
	if left < 0 {
		left = 0
	}
	right := left + l.height
	if right > total {
		right = total
	}
	if left > right {
		left = right
	}
	return strings.Join(lines[left:right], "\n")
}

